<div class="w-full max-w-[430px] mx-auto flex flex-col gap-5"><header class="flex items-center justify-between border-b pb-3"><a href="/admin/laporan" class="w-10 h-10 rounded-full bg-white border flex items-center justify-center">←</a><div class="text-center"><h1 class="text-lg font-bold text-[#1B4332]">Laporan Siswa</h1><p class="text-[11px] text-gray-500">Monitoring Kehadiran & Nilai</p></div><span class="w-2.5 h-2.5 rounded-full bg-emerald-500"></span></header><div class="grid grid-cols-2 p-1 bg-[#ECEAE6] rounded-xl gap-1"><span class="py-2 rounded-lg text-xs font-bold text-center bg-[#1B4332] text-white">Harian</span><a class="py-2 rounded-lg text-xs font-semibold text-center text-gray-600" href="/admin/laporan/siswa?mode=bulanan">Bulanan</a></div><form class="bg-white rounded-2xl p-4 border flex flex-col gap-3"><label class="text-[10px] font-bold uppercase text-gray-500">Tanggal Laporan</label><input type="date" name="tanggal" value="<?=e($tanggal)?>" class="rounded-xl border-gray-200"><select name="kelas_id" class="rounded-xl border-gray-200"><option value="0">Semua Kelas</option><?php foreach($kelasList as $k): ?><option value="<?=$k['id']?>" <?=$kelasId==(int)$k['id']?'selected':''?>><?=e($k['nama'])?></option><?php endforeach;?></select><button class="py-2 rounded-xl bg-[#1B4332] text-white text-xs font-bold">Tampilkan</button></form><?php if(empty($report)): ?><div class="bg-white rounded-2xl p-8 text-center text-gray-500 border">Tidak ada data presensi pada tanggal ini.</div><?php else: ?><div class="flex flex-col gap-2"><?php foreach($report as $r): ?><div class="bg-white rounded-2xl p-4 border flex justify-between"><div><b><?=e($r['siswa_nama'])?></b><p class="text-xs text-gray-500"><?=e($r['kelas_nama'])?></p></div><span class="text-xs font-semibold"><?=e(ucfirst($r['status_kehadiran'] ?: 'Belum diisi'))?></span></div><?php endforeach;?></div><?php endif;?></div>
